import sys
import json

sysin = json.loads(sys.stdin.read() or "null")

base = sysin.get("base")
files = sysin.get("files") or []

out = dict(base or {})

for f in files:
    pc = None
    if isinstance(f, dict):
        pc = f.get("problemCounts")
    for k, v in (pc or {}).items():
        try:
            n = int(v)
        except Exception:
            continue
        if n <= 0:
            continue
        out[k] = out.get(k, 0) + n

result = out

print(json.dumps(result, ensure_ascii=False))

import sys
import json

sysin = json.loads(sys.stdin.read() or "null")

category = sysin.get("category")
files = sysin.get("files") or []

files_total = 0

for f in files:
    pc = None
    if isinstance(f, dict):
        pc = f.get("problemCounts")
    out = 0
    for k, v in (pc or {}).items():
        try:
            n = int(v)
        except Exception:
            continue
        if n <= 0:
            continue
        if k == category:
            out += n
        else:
            # 実際にはログ警告だがここでは何もしない
            pass
    files_total += out

result = files_total

print(json.dumps(result, ensure_ascii=False))
